"""Byte-sequence API for the compressed payload extension.

Sequences are kept as small expression trees so that very large logical byte
objects (repetitions of a compact literal) never need to be expanded.  Only
bounded windows are ever materialised; lengths and fingerprints are derived
algebraically from the tree shape.
"""
import ast
import bisect
import hashlib
import keyword
import re

MAX = (1 << 63) - 1
MASK = (1 << 64) - 1
BASE = 257
MODULUS = 1 << 64

NAME_SOURCE = 8192
TEMPLATE_SOURCE = 65536
MAX_DEPTH = 128

_TOKEN = re.compile(r'[A-Za-z][A-Za-z0-9_]{0,31}\Z')
RANDOM_TOKEN = '<<random_string>>'


# --------------------------------------------------------------------------- #
# fingerprints
# --------------------------------------------------------------------------- #

def hash_bytes(data):
    """Exact checksum: sum((b[i]+1)*257**(n-1-i)) mod 2**64."""
    h = 0
    for value in data:
        h = (h * BASE + value + 1) & MASK
    return h


def combine(left, right):
    """Fingerprint pair (length, hash) of a concatenation."""
    (ln, lh), (rn, rh) = left, right
    if ln == 0:
        return right
    if rn == 0:
        return left
    return (ln + rn, (lh * pow(BASE, rn, MODULUS) + rh) & MASK)


def _geom(power, count):
    """(sum(power**i for i < count) mod 2**64, power**count mod 2**64)."""
    if count <= 0:
        return 0, 1
    if count == 1:
        return 1, power % MODULUS
    if count % 2 == 0:
        half, sq = _geom(power, count // 2)
        return (half * (1 + sq)) & MASK, (sq * sq) & MASK
    total, pw = _geom(power, count - 1)
    return (total + pw) & MASK, (pw * power) & MASK


def repeat_hash(inner_hash, inner_len, count):
    """Fingerprint hash of ``inner`` repeated ``count`` times."""
    if count <= 0 or inner_len == 0:
        return 0
    return (inner_hash * _geom(pow(BASE, inner_len, MODULUS), count)[0]) & MASK


def fingerprint(node):
    if node is None:
        node = EMPTY
    return {'n': node.length, 'h': '%016x' % node.hash}


# --------------------------------------------------------------------------- #
# sequence nodes
# --------------------------------------------------------------------------- #

class Node:
    __slots__ = ('length', '_hash')

    def __init__(self, length):
        self.length = length
        self._hash = None

    @property
    def hash(self):
        h = self._hash
        if h is None:
            h = self._hash = self.compute()
        return h

    def compute(self):
        raise NotImplementedError

    def __repr__(self):
        return '%s(%d)' % (type(self).__name__, self.length)


class Lit(Node):
    __slots__ = ('data',)

    def __init__(self, data):
        super().__init__(len(data))
        self.data = data

    def compute(self):
        return hash_bytes(self.data)


class Cat(Node):
    __slots__ = ('parts', 'offsets')

    def __init__(self, parts):
        total = 0
        for part in parts:
            total += part.length
            if total > MAX:
                raise ValueError('sequence length')
        super().__init__(total)
